use super::{map_runtime_inputs, InputMappingError};
use std::error::Error;
use vb_core::{SlotIdx, SlotValue};
use vb_core::ids::{StepIdx, WorkflowDigest};
use vb_core::workflow::{CompiledWorkflow, CompiledNode, CompiledNodeKind, CompiledInputSlot, InputSlotKind, WorkflowParts, ResourceContract};

type TestResult<T> = Result<T, Box<dyn Error>>;

fn fixture(input_slots: Box<[CompiledInputSlot]>) -> TestResult<CompiledWorkflow> {
    let node = CompiledNode {
        id: StepIdx::ZERO, output: None, next: None, on_error: None, error_slot: None,
        kind: CompiledNodeKind::Finish { result: SlotIdx::new(2) },
    };
    let parts = WorkflowParts {
        name: Box::from("input-mapping"), digest: WorkflowDigest::from_bytes([1;32]),
        nodes: Box::from([node]), expressions: Box::from([]), accessors: Box::from([]),
        constants: Box::from([]), slot_count: 4, symbols_count: 0, entry: StepIdx::ZERO,
        resource_contract: ResourceContract::DEFAULT, step_names: Box::from([]), input_slots,
    };
    CompiledWorkflow::try_from_parts(parts).map_err(|error| error.to_string().into())
}

fn i64_port() -> CompiledInputSlot { CompiledInputSlot { slot: SlotIdx::new(2), kind: InputSlotKind::I64 } }
fn bool_port() -> CompiledInputSlot { CompiledInputSlot { slot: SlotIdx::new(3), kind: InputSlotKind::Bool } }

#[test]
fn zeroports_raw_empty() -> TestResult<()> {
    let wf = fixture(Box::from([]))?;
    let result = map_runtime_inputs(&wf, &[]);
    assert_eq!(result, Ok(Box::from([])));
    Ok(())
}

#[test]
fn zeroports_encoded_empty() -> TestResult<()> {
    let wf = fixture(Box::from([]))?;
    let mut buf = postcard::to_allocvec(&Box::<[SlotValue]>::from([]))?;
    buf.push(0);
    let result = map_runtime_inputs(&wf, &buf);
    assert_eq!(result, Ok(Box::from([])));
    Ok(())
}

#[test]
fn zeroports_malformed_255() -> TestResult<()> {
    let wf = fixture(Box::from([]))?;
    let buf: Vec<u8> = vec![255];
    let result = map_runtime_inputs(&wf, &buf);
    assert_eq!(result, Err(InputMappingError::DecodeFailed));
    Ok(())
}

#[test]
fn zeroports_one_i64() -> TestResult<()> {
    let wf = fixture(Box::from([]))?;
    let mut buf = postcard::to_allocvec(&Box::from([SlotValue::I64(99)]))?;
    buf.push(0);
    let result = map_runtime_inputs(&wf, &buf);
    assert_eq!(result, Err(InputMappingError::SlotCountExceeded));
    Ok(())
}

#[test]
fn zeroports_encoded_empty_plus_255() -> TestResult<()> {
    let wf = fixture(Box::from([]))?;
    let mut buf = postcard::to_allocvec(&Box::<[SlotValue]>::from([]))?;
    buf.push(255);
    let result = map_runtime_inputs(&wf, &buf);
    assert_eq!(result, Err(InputMappingError::DecodeFailed));
    Ok(())
}

#[test]
fn with_i64_port_empty_raw() -> TestResult<()> {
    let wf = fixture(Box::from([i64_port()]))?;
    let result = map_runtime_inputs(&wf, &[]);
    assert_eq!(result, Ok(Box::from([])));
    Ok(())
}

#[test]
fn slot2_i64_mapping_i64_42() -> TestResult<()> {
    let wf = fixture(Box::from([i64_port()]))?;
    let mut buf = postcard::to_allocvec(&Box::from([SlotValue::I64(42)]))?;
    buf.push(0);
    let result = map_runtime_inputs(&wf, &buf);
    assert_eq!(result, Ok(Box::from([(SlotIdx::new(2), SlotValue::I64(42))])));
    Ok(())
}

#[test]
fn slots_2_i64_3_bool_partial_1_maps_2() -> TestResult<()> {
    let wf = fixture(Box::from([i64_port(), bool_port()]))?;
    let mut buf = postcard::to_allocvec(&Box::from([SlotValue::I64(11)]))?;
    buf.push(0);
    let result = map_runtime_inputs(&wf, &buf);
    assert_eq!(result, Ok(Box::from([(SlotIdx::new(2), SlotValue::I64(11))])));
    Ok(())
}

#[test]
fn full_2_correct_order() -> TestResult<()> {
    let wf = fixture(Box::from([i64_port(), bool_port()]))?;
    let mut buf = postcard::to_allocvec(&Box::from([SlotValue::I64(1), SlotValue::Bool(true)]))?;
    buf.push(0);
    let result = map_runtime_inputs(&wf, &buf);
    assert_eq!(result, Ok(Box::from([
        (SlotIdx::new(2), SlotValue::I64(1)),
        (SlotIdx::new(3), SlotValue::Bool(true)),
    ])));
    Ok(())
}

#[test]
fn i64_port_bool() -> TestResult<()> {
    let wf = fixture(Box::from([i64_port()]))?;
    let mut buf = postcard::to_allocvec(&Box::from([SlotValue::Bool(true)]))?;
    buf.push(0);
    let result = map_runtime_inputs(&wf, &buf);
    assert_eq!(result, Err(InputMappingError::KindMismatch {
        slot: SlotIdx::new(2),
        expected: InputSlotKind::I64,
    }));
    Ok(())
}

