fn ports_255() -> TestResult<()> {
    let wf = fixture(Box::from([i64_port()]))?;
    let buf: Vec<u8> = vec![255];
    let result = map_runtime_inputs(&wf, &buf);
    assert_eq!(result, Err(InputMappingError::DecodeFailed));
    Ok(())
}

